update xf_uniform_style
style_code = #{styleCode}, style_name = #{styleName}, season = #{season}, style_type = #{styleType}, gender = #{gender}, fabric_name = #{fabricName}, fabric_composition = #{fabricComposition}, code_mode = #{codeMode}, special_body_support = #{specialBodySupport}, care_instructions = #{careInstructions}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
